head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDBNS20500.xml';
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vIsurNm, scwin.vIsurNmTpCd, scwin.vDuplCnt;
scwin.gBndApplId;
scwin.gAllChk = false, scwin.gDelRowChk = false;
scwin.gApplDdTm = '', scwin.gAcptDdTm = '';
scwin.processGp; //파일 연결 1, 파일 삭제 5
scwin.vDelParam = new Object();
scwin.vModParam = new Object();
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SetComboCode
 * 설명       : 콤보데이터 정의 (채권시장조치구분코드)
 ***********************************************/
scwin.fn_SetComboCode = function() {
    var arrCid = [];
    arrCid.push({
        cid: '03057',
        cnm: 'cmb_MktactTpCd'
    });
    $c.bns.fn_SetBnsComboToCode2(scwin.vScrenID, dts_Temp, arrCid, 'ALL');
};


/********************************************** 
 * 함수명  	 : fn_Search
 * 설명       : 리스트를 조회 한다.
 ***********************************************/
scwin.fn_Search = function() {
    var dsNm = 'BNS_FILE_APPL_LIST';
    var qryId = 'lds.stf.bnslistbzappl.select.listFileConnAppl';
    var param = '';
    param += '&{P}V_ISUR_CD=' + $c.stf.getObjectValue(txb_ApplIsurNm);
    param += '&{P}V_APPL_START_DD=' + $c.stf.getObjectValue(edt_ApplStartDd);
    param += '&{P}V_APPL_END_DD=' + $c.stf.getObjectValue(edt_ApplEndDd);
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List);
};

/********************************************** 
 * 함수명  	 : fn_BndAcptSearch
 * 설명       : 채권 신청정보 리스트를 조회 한다.
 ***********************************************/
scwin.fn_BndAcptSearch = function(rowNum) {
    var dsNm = 'BNS_FILE_OR_FAX_ACPT_LIST';
    var qryId = 'lds.stf.bnslistbzappl.select.listFileConnBndAcpt';
    var param = '';
    param += '&{P}V_ISUR_CD=' + $c.stf.getObjectValue(txb_AcptIsurNm);
    param += '&{P}V_ACPT_START_DD=' + $c.stf.getObjectValue(edt_AcptStartDd);
    param += '&{P}V_ACPT_END_DD=' + $c.stf.getObjectValue(edt_AcptEndDd);
    param += '&{P}V_ISU_NM=' + $c.stf.getObjectValue(txb_IsuNm);
    param += '&{P}V_MKTACT_TP_CD=' + $c.stf.getObjectValue(cmb_MktactTpCd);
    if (rowNum > 0) {
        param += '&{P}V_BND_APPL_ID=' + dts_List.getCellData(rowNum, "BND_APPL_ID"); //접수번호추가 2023.08.21 by no3.

    }
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_AcptList, dsNm, qryId, param);
    var arrPnl = [pnl_AcptSrch];
    $c.bns.ShowWinArrPnl(arrPnl, grd_AcptList);
};

/********************************************** 
 * 함수명  	 : fn_FileConnSearch
 * 설명       : 증권신고서 연결정보 리스트를 조회 한다.
 ***********************************************/
scwin.fn_FileConnSearch = function() {
    var dsNm = 'BNS_FILE_CONN_LIST';
    var qryId = 'lds.stf.bnslistbzappl.select.listFileConnInfo';
    var param = '&{P}V_BND_APPL_ID=' + scwin.gBndApplId;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_ConList, dsNm, qryId, param);
};

/********************************************** 
 * 함수명  	 : fn_DuplChkFileConn
 * 설명       : 증권신고서 연결정보 중복 체크
 ***********************************************/
scwin.fn_DuplChkFileConn = function() {
    var dsNm = 'BNS_BND_APPL_ID_NEXTVAL';
    var qryId = 'lds.stf.bnslistbzappl.select.listFileConnDuplChk';
    //파라미터설정
    var param = '';
    param += '&{P}V_APPL_DD=' + scwin.gApplDdTm.APPL_DD;
    param += '&{P}V_APPL_TM=' + scwin.gApplDdTm.APPL_TM;
    param += '&{P}V_ISUR_CD=' + scwin.gApplDdTm.ISUR_CD;
    param += '&{P}V_BND_APPL_ID=' + scwin.gAcptDdTm;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_CheckDuplConList, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: scwin.vIsurNm
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    if (scwin.vIsurNmTpCd == 'Appl') {
        $c.stf.setObjectValue(txb_ApplIsurNm, arrPar[0].ISUR_CD);
    } else if (scwin.vIsurNmTpCd == 'Acpt') {
        $c.stf.setObjectValue(txb_AcptIsurNm, arrPar[0].ISUR_CD);
    }
};


/********************************************** 
 * 함수명   : fn_ShowIsur
 * 설명       : 발행기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowIsur = function(vIsurNm) {
    scwin.fn_GetPar = fn_GetParIsurCd;
    scwin.fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(lbl_ApplTitle);
};


/********************************************** 
 * 함수명   : fn_GetParIsuCd
 * 설명       : 상장채권종목 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsuCd = function(arrPar) {
    arrPar[0] = {
        LIST_TYPE_CD: '2',
        ISU_NM: $c.stf.getObjectValue(txb_IsuNm),
        ISUR_NM: $c.stf.getObjectValue(txb_AcptIsurNm)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsuCd
 * 설명       : 상장채권종목 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsuCd = function(arrPar) {
    $c.stf.setObjectValue(txb_IsuNm, arrPar[0].STD_CD);
};

/********************************************** 
 * 함수명   : fn_ShowIsu
 * 설명       : 상장채권종목 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowIsu = function(IsuNm) {
    scwin.fn_GetPar = fn_GetParIsuCd;
    scwin.fn_SetPar = fn_SetParIsuCd;
    $c.bns.fn_PopListBndIsuSearch(txb_IsuNm);
};


/********************************************** 
 * 함수명   : fn_ApplGetApplDdAndTm
 * 설명       : 증권신고서 접수정보의 체크된 접수일시 반환
 ***********************************************/
scwin.fn_ApplGetApplDdAndTm = function() {
    var chk = '';
    var returnValApplDd = '',
        returnValApplTm = '',
        returnValIsuCd = '';
    var applDd, applTm;
    var objReturnVal = new Object();
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        chk = dts_List.getCellData(i, "CHECKED");
        if (chk == "T" || chk == "1") {
            applDd = dts_List.getCellData(i, 'APPL_DD_TM').substring(0, 8);
            applTm = dts_List.getCellData(i, 'APPL_DD_TM').substring(8, 17);
            returnValApplDd += "'" + applDd + "',";
            returnValApplTm += "'" + applTm + "',";
            returnValIsuCd += "'" + dts_List.getCellData(i, 'ISUR_CD') + "',";
        }
    }
    objReturnVal.APPL_DD = returnValApplDd.substring(0, returnValApplDd.length - 1);
    objReturnVal.APPL_TM = returnValApplTm.substring(0, returnValApplTm.length - 1);
    objReturnVal.ISUR_CD = returnValIsuCd.substring(0, returnValIsuCd.length - 1);
    return objReturnVal;
};

/********************************************** 
 * 함수명   : fn_AcptGetApplDdAndTm
 * 설명       : 채권 신청정보의 체크된 접수번호 반환
 ***********************************************/
scwin.fn_AcptGetApplDdAndTm = function() {
    var chk = '';
    var returnVal = '';
    for (var i = 1; i <= dts_AcptList.getTotalRow(); i++) {
        chk = dts_AcptList.getCellData(i, "CHECKED");
        if (chk == "T" || chk == "1") {
            returnVal += "'" + dts_AcptList.getCellData(i, 'BND_APPL_ID') + "',";
        }
    }
    return returnVal.substring(0, returnVal.length - 1);
};


/********************************************** 
 * 함수명   : fn_FileConnCheck
 * 설명       : 파일 연결 체크
 ***********************************************/
scwin.fn_FileConnCheck = function() {
    if (scwin.gApplDdTm.APPL_DD == '') {
        $c.win.alert("유가증권신고서 접수정보에서 연결할 문서를 선택하십시오!");
        return false;
    }
    if (scwin.gAcptDdTm == '') {
        $c.win.alert("채권신청정보에서 데이타를 선택하십시오!");
        return false;
    }
    return true;
};


/********************************************** 
 * 함수명   : fn_Insert
 * 설명       : 파일 연결
 ***********************************************/
scwin.fn_Insert = function() {
    var url;
    if (scwin.fn_FileConnCheck() == false) return;
    if (!confirm("문서를 연결 하시겠습니까?")) return false;
    if (dts_CheckDuplConList.getTotalRow() > 0) {
        $c.win.alert("이미 문서가 연결되어 있습니다.!");
        return false;
    }
    url = "/bns/FileFaxConn.do?method=processAttachDocConn";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    url += "&APPL_DD=" + scwin.gApplDdTm.APPL_DD;
    url += "&APPL_TM=" + scwin.gApplDdTm.APPL_TM;
    url += "&ISUR_CD=" + scwin.gApplDdTm.ISUR_CD;
    url += "&BND_APPL_ID=" + scwin.gAcptDdTm;
    url += "&FILE_FAX=" + 'FILE';
    dts_List.UseChangeInfo = "False";
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_List)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_Del
 * 설명       : 파일 연결 삭제
 ***********************************************/
scwin.fn_Del = function() {
    if (scwin.gDelRowChk == false) {
        $c.win.alert("유가증권신고서 연결정보에서 데이타를 선택하십시오!");
        return;
    }
    if (!confirm("연결된문서를 삭제하시겠습니까?")) return false;
    var url;
    url = "/bns/FileFaxConn.do?method=delete";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    url += "&ISUR_CD=" + scwin.vDelParam.ISUR_CD;
    url += "&APPL_DD=" + scwin.vDelParam.APPL_DD;
    url += "&APPL_TM=" + scwin.vDelParam.APPL_TM;
    url += "&BND_APPL_ID=" + scwin.vDelParam.BND_APPL_ID;
    url += "&FILE_FAX=" + 'FILE';
    dts_ConList.UseChangeInfo = "False";
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_ConList)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_Del_File
 * 설명       : 파일 원본 삭제
 ***********************************************/
scwin.fn_Del_File = function() {
    if (dts_List.getTotalRow() < 1) {
        return;
    }
    if (dts_List.getRowPosition() < 1) {
        $c.win.alert("삭제할 파일을 선택하세요.");
        return;
    }
    if (!confirm("선택한 파일(원본)을 삭제하시겠습니까?\n\n(시스템관리자 권한)")) return false;
    var url;
    url = "/bns/FileFaxConn.do?method=deleteFile";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    url += "&ISUR_CD=" + scwin.vDelParam.ISUR_CD;
    url += "&APPL_DD=" + scwin.vDelParam.APPL_DD;
    url += "&APPL_TM=" + scwin.vDelParam.APPL_TM;
    url += "&FILE_FAX=" + 'FILE';
    dts_List.UseChangeInfo = "False";
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_List)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_ModAttachFileTpCd
 * 설명       : 첨부파일구분코드 수정 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_ModAttachFileTpCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: scwin.vModParam.ISUR_CD,
        APPL_DD_TM: scwin.vModParam.APPL_DD_TM
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetModAttachFileTpCd
 * 설명       : 첨부파일구분코드 수정 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetModAttachFileTpCd = function(arrPar) {
    if ("Y" == arrPar[0].MOD_YN) {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
        dts_ConList.Reset();
    }
};



/******************************************************************* 
 * 함수명   : fn_PopModAttachFileTpCd
 * 설명     : 첨부파일구분코드 수정 팝업을 보여준다.
 * argument : object
 *******************************************************************/
scwin.fn_PopModAttachFileTpCd = async function(grdObj) {
    $c.bns.fn_SetPopupPos(grdObj, 'E');
    await $c.frame.CreateDialogFrame("ULDBNS20501", "/bnslistbzappl/ULDBNS20501.gfm", "파일구분 수정", obj_left, obj_top, 530, 260, "window");
};


/*************************
 * 함수명   : fn_FileDownload
 * 설명     : 파일 다운로드
 * argument : object
 *************************/
scwin.fn_FileDownload = function(row) {
    if (dts_List.getCellData(row, "FAX_IMG_FILE_NM") == "") {
        return;
    } else {
        var url = "/bns/BnsAttachDocFileDownload.do";
        url += "?ATTACH_FILE_TP_CD=" + 2;
        url += "&ISUR_CD=" + dts_List.getCellData(row, "ISUR_CD");
        var vApplDdTm = dts_List.getCellData(row, "APPL_DD_TM");
        url += "&APPL_DD=" + vApplDdTm.substring(0, 8);
        url += "&APPL_TM=" + vApplDdTm.substring(8, 14);
        location.href = url;
    }
};



/********************************************** 
 * 함수명   : fn_SetFileUpLoad
 * 설명       : 파일업 로드 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetFileUpLoad = function(arrPar) {
    if ("Y" == arrPar[0].FILE_UP) {
        $c.win.alert($c.stf.getMessageParam("MSG-0001"));

        //조회조건 설정
        $c.stf.setObjectValue(edt_ApplStartDd, scwin.vCurDate);
        $c.stf.setObjectValue(edt_ApplEndDd, scwin.vCurDate);
        //setObjectValue(txb_ApplIsurNm, arrPar[0].ISUR_NM);
        //조회
        scwin.fn_Search();
    }
};


/******************************************************************* 
 * 함수명   : fn_PopFileUpLoad
 * 설명     : 파일 업로드 팝업을 보여준다.
 * argument : object
 *******************************************************************/
scwin.fn_PopFileUpLoad = async function(grdObj) {
    $c.bns.fn_SetPopupPos(grdObj, 'E');
    await $c.frame.CreateDialogFrame("ULDBNS20502", "/bnslistbzappl/ULDBNS20502.gfm", "파일업로드", obj_left, obj_top, 920, 270, "window");
};


/******************************************************************* 
 * 함수명     : fn_ctrlCheckBox
 * 설명        : 접수번호가 동일한 첨부파일은 모두 선택되도록
 * argument : rowNum
 *******************************************************************/
scwin.fn_ctrlCheckBox = function(rowNum, bCheck) {
    if (bCheck != "1") {
        return;
    }
    var bnd_appl_id = dts_List.getCellData(rowNum, "BND_APPL_ID");
    if (bnd_appl_id == "") {
        return;
    }
    grd_List.Redraw = false;
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        if (bnd_appl_id == dts_List.getCellData(i, 'BND_APPL_ID')) {
            dts_List.setCellData(i, "CHECKED", "T");
        }
    }
    grd_List.Redraw = true;
};
scwin.gform_onload = function() {
    //숨기기
    if (js_usr_tp_cd == '1') {
        //운영자이면
        $c.stf.showObj(btn_Del_File, true);
    } else {
        $c.stf.showObj(btn_Del_File, false);
    }

    // 패널라운드 처리
    $c.bns.BnsPanelToGroupBox(pnl_list);
    $c.bns.BnsPanelToGroupBox(pnl_Srch);
    $c.bns.BnsPanelToGroupBox(pnl_AcptSrch);

    //채권시장조치구분코드
    scwin.fn_SetComboCode();

    //접수 조회 시작일 -7일, 종료일 현재일자로 설정
    $c.stf.setObjectValue(edt_ApplStartDd, $c.ut.cGetMinusDate2(scwin.vCurDate, 7));
    $c.stf.setObjectValue(edt_ApplEndDd, scwin.vCurDate);

    //신청 조회 시작일 -7일, 종료일 현재일자로 설정
    $c.stf.setObjectValue(edt_AcptStartDd, $c.ut.cGetMinusDate2(scwin.vCurDate, 30));
    $c.stf.setObjectValue(edt_AcptEndDd, scwin.vCurDate);

    //fn_BndAcptSearch();
    scwin.fn_Search();
};
scwin.img_ApplStartDd_onclick = function() {
    popUpCalendar2(edt_ApplStartDd);
};
scwin.img_ApplEndDd_onclick = function() {
    popUpCalendar2(edt_ApplEndDd);
};
scwin.txb_ApplIsurNm_onkeypress = function() {
    if ($c.stf.compareFromToDate2(edt_ApplStartDd, edt_ApplEndDd)) {
        if (window.event.keyCode == 13) scwin.fn_Search();
    }
};
scwin.img_ApplIsurNm_onclick = function() {
    scwin.vIsurNmTpCd = 'Appl';
    scwin.vIsurNm = $c.stf.getObjectValue(txb_ApplIsurNm);
    scwin.fn_ShowIsur(scwin.vIsurNm);
};
scwin.btn_ApplSearch_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_ApplStartDd, edt_ApplEndDd)) {
        scwin.fn_Search();
    }
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    scwin.gDelRowChk = false;
    dts_List.setRowPosition(0, 0);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.grd_List_OnClick = function(row, colid) {
    scwin.gDelRowChk = true;
    scwin.vDelParam.ISUR_CD = dts_List.getCellData(row, "ISUR_CD");
    scwin.vDelParam.APPL_DD = dts_List.getCellData(row, "APPL_DD");
    scwin.vDelParam.APPL_TM = dts_List.getCellData(row, "APPL_TM");
    $c.stf.setObjectValue(txb_AcptIsurNm, dts_List.getCellData(row, "ISUR_NM"));
    scwin.fn_BndAcptSearch(row);
};
scwin.grd_List_OnCheckClick = function(col, colid, bCheck) {
    $c.bns.fn_IsChecked(dts_List, "CHECKED");

    /*
     * 접수번호가 동일한 것들을 모두 체크한다.
     */
    scwin.fn_ctrlCheckBox(col, bCheck);
};
scwin.grd_List_OnDblClick = function(row, colid) {
    if (dts_List.getTotalRow() == 0) return;
    if (row > 0) {
        if (colid == "ORGN_FILE_NM") {
            scwin.fn_FileDownload(row);
        }
    }
};
scwin.img_AcptStartDd_onclick = function() {
    popUpCalendar2(edt_AcptStartDd);
};
scwin.img_AcptEndDd_onclick = function() {
    popUpCalendar2(edt_AcptEndDd);
};
scwin.txb_AcptIsurNm_onkeypress = function() {
    if ($c.stf.compareFromToDate2(edt_AcptStartDd, edt_AcptEndDd)) {
        if (window.event.keyCode == 13) scwin.fn_BndAcptSearch();
    }
};
scwin.img_AcptIsurNm_onclick = function() {
    scwin.vIsurNmTpCd = 'Acpt';
    scwin.vIsurNm = $c.stf.getObjectValue(txb_AcptIsurNm);
    scwin.fn_ShowIsur(scwin.vIsurNm);
};
scwin.img_IsuNm_onclick = function() {
    scwin.fn_ShowIsu();
};
scwin.txb_IsuNm_onkeypress = function() {
    if ($c.stf.compareFromToDate2(edt_AcptStartDd, edt_AcptEndDd)) {
        if (window.event.keyCode == 13) scwin.fn_BndAcptSearch();
    }
};
scwin.btn_AcptSearch_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_AcptStartDd, edt_AcptEndDd)) {
        scwin.fn_BndAcptSearch(-1);
    }
};
scwin.dts_AcptList_OnLoadCompleted = function(rowcount) {
    var arrPnl = [pnl_AcptSrch];
    $c.bns.CloseWinArrPnl(rowcount, arrPnl, grd_AcptList);
    if (rowcount == 1) {
        dts_AcptList.setCellData(1, "CHECKED", "T");
    }
};
scwin.dts_AcptList_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.grd_AcptList_OnHeadCheckClick = function(col, colid, bCheck) {
    $c.bns.fn_SetAllCheckBox(grd_AcptList, dts_AcptList, bCheck);
};
scwin.grd_AcptList_OnCheckClick = function(col, colid, bCheck) {
    $c.bns.fn_IsChecked(dts_AcptList, "CHECKED");
};
scwin.btn_FileCon_onclick = function() {
    scwin.processGp = 1;
    scwin.gApplDdTm = scwin.fn_ApplGetApplDdAndTm();
    scwin.gAcptDdTm = scwin.fn_AcptGetApplDdAndTm();
    scwin.fn_DuplChkFileConn();
    scwin.fn_Insert();
};
scwin.dts_AcptList_OnRowPosChanged = function(row) {
    scwin.gBndApplId = dts_AcptList.getCellData(row, "BND_APPL_ID");
    scwin.fn_FileConnSearch();
};
scwin.dts_ConList_OnLoadCompleted = function(rowcount) {
    scwin.gDelRowChk = false;
    dts_ConList.setRowPosition(0, 0);
};
scwin.dts_ConList_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.grd_ConList_OnClick = function(row, colid) {
    scwin.gDelRowChk = true;
    scwin.vDelParam.ISUR_CD = dts_ConList.getCellData(row, "ISUR_CD");
    scwin.vDelParam.APPL_DD = dts_ConList.getCellData(row, "APPL_DD");
    scwin.vDelParam.APPL_TM = dts_ConList.getCellData(row, "APPL_TM");
    scwin.vDelParam.BND_APPL_ID = dts_ConList.getCellData(row, "BND_APPL_ID");
};
scwin.btn_Del_onclick = function() {
    if (dts_ConList.getTotalRow() == 0) return;
    scwin.processGp = 5;
    scwin.fn_Del();
};
scwin.btn_Del_File_onclick = function() {
    if (dts_List.getTotalRow() == 0) return;
    scwin.processGp = 5;
    scwin.fn_Del_File();
};
scwin.btn_Mod_onclick = function() {
    if (dts_ConList.getTotalRow() == 0) return;
    if (scwin.gDelRowChk == false) {
        $c.win.alert("유가증권신고서 연결정보에서 데이타를 선택하십시오!");
        return;
    }
    scwin.vModParam.ISUR_CD = dts_ConList.getCellData(dts_ConList.getRowPosition(), "ISUR_CD");
    scwin.vModParam.APPL_DD_TM = dts_ConList.getCellData(dts_ConList.getRowPosition(), "APPL_DD_TM");
    scwin.fn_GetPar = fn_ModAttachFileTpCd;
    scwin.fn_SetPar = fn_SetModAttachFileTpCd;
    scwin.fn_PopModAttachFileTpCd(grd_List);
};
scwin.trs_Save_OnSuccess = function() {
    if (scwin.processGp == 1) {
        $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    }
    if (scwin.processGp == 5) {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    }
    dts_List.Reset();
    dts_AcptList.Reset();
    dts_ConList.Reset();
};
scwin.trs_Save_OnFail = function() {
    if (scwin.processGp == 1) {
        $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    }
    if (scwin.processGp == 5) {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
    }
};
scwin.btn_FileUp_onclick = function() {
    scwin.fn_SetPar = fn_SetFileUpLoad;
    scwin.fn_PopFileUpLoad(grd_List);
};
scwin.grd_List_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.grd_AcptList_CanColumnPosChange = function(row, colid) {
    return true;
};
